INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(6901, '1 Samuel 9:17', '1 Samuel', 9, 17, '&nbsp;کله چې د سموئيل نظر په ساؤل پرېوتو، نو مالِک خُدائ هغۀ ته وفرمائيل، ”دا هغه سړے دے چې د هغۀ په حقله ما درته فرمائيلى وُو. هغه به زما په خلقو بادشاهى کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6902, '1 Samuel 9:18', '1 Samuel', 9, 18, '&nbsp;بيا ساؤل سموئيل له ورَغلو، چې د دروازې په خولۀ کښې وو او تپوس يې ترې نه وکړو، ”مِهربانى وکړه او ما ته ووايه چې هغه پېشګوئې ورکوونکے چرته اوسيږى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6903, '1 Samuel 9:19', '1 Samuel', 9, 19, '&nbsp;سموئيل ورته وفرمائيل، ”زۀ پېشګوئې ورکوونکے يم. زما نه وړاندې د عبادت ځائ ته روان شئ. تاسو دواړه به نن ما سره روټۍ خورئ. سبا سحر به زۀ تا ته هغه څۀ وښايم چې ستا په زړۀ کښې وى او تاسو به رُخصت کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6904, '1 Samuel 9:20', '1 Samuel', 9, 20, '&nbsp;چې کوم خرونه درې ورځې مخکښې ورک شوى وُو، د هغې فکر مۀ کوئ، هغه پېدا شوى دى. خو دا تۀ او ستا د پلار خاندان دے چې د ټولو بنى اِسرائيلو زړۀ ور پورې تړلے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6905, '1 Samuel 9:21', '1 Samuel', 9, 21, '&nbsp;ساؤل ورته په جواب کښې ووئيل، ”زۀ د بنيامين د قبيلې يم، کومه چې د بنى اِسرائيلو د ټولو نه وړه قبيله وه او په قبيله کښې زما د خاندان اهميت د ټولو نه کم دے. نو بيا، تۀ زما سره داسې خبرې ولې کوې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6906, '1 Samuel 9:22', '1 Samuel', 9, 22, '&nbsp;بيا سموئيل ساؤل او د هغۀ نوکر يې يوې غټې کوټې ته بوتلل او هغوئ له يې د دسترخوان په سر کښې ځائ ورکړو چرته چې تقريباً ټول دېرش کسان ناست وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6907, '1 Samuel 9:23', '1 Samuel', 9, 23, '&nbsp;سموئيل د اخلى پخلى والا ته وفرمائيل، ”د غوښې هغه ټُکړه راوړه چې ما درکړې وه او درته مې فرمائيلى وُو چې جدا يې کېږده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6908, '1 Samuel 9:24', '1 Samuel', 9, 24, '&nbsp;نو د اخلى پخلى والا د ټولو نه ښۀ غوښه راوړه او د ساؤل په مخکښې يې کېښوده. سموئيل ورته وفرمائيل، ”ګوره، دا هغه ټُکړه ده چې ستا دپاره ساتلے شوې وه. دا وخوره. د دې خلقو د رابللو نه مخکښې دا ما ستا دپاره اېښې وه.“ نو ساؤل په هغه ورځ د سموئيل سره روټۍ وخوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6909, '1 Samuel 9:25', '1 Samuel', 9, 25, '&nbsp;کله چې هغوئ د عبادت ځائ نه ښار ته کوز شول، نو هغوئ په چت باندې د ساؤل دپاره د څملاستو ځائ تيار کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6910, '1 Samuel 9:26', '1 Samuel', 9, 26, '&nbsp;او هغه هلته اودۀ شو. د ساؤل د بادشاه په توګه مقرر کېدل په سحر کښې سموئيل ساؤل ته په چت باندې آواز وکړو، ”پاڅه او زۀ به تا رُخصت کړم.“ ساؤل پاڅېدو او هغه او سموئيل دواړه يو ځائ بهر کوڅې ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6911, '1 Samuel 9:27', '1 Samuel', 9, 27, '&nbsp;کله چې هغوئ د ښار سر ته ورسېدل، نو سموئيل ساؤل ته وفرمائيل، ”نوکر ته ووايه چې زمونږ نه مخکښې روان شى.“ نوکر لاړو او سموئيل خپله خبره جارى وساتله، ”لږ وخت دلته ايسار شه، نو زۀ به تا ته د خُدائ پاک د طرف نه يوه خبره وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6912, '1 Samuel 10:1', '1 Samuel', 10, 1, '&nbsp;بيا سموئيل د زيتُونو تېلو يو لوښے واخستو او تېل يې د ساؤل په سر واړول، ساؤل يې ښُکل کړو او ورته يې وفرمائيل، ”مالِک خُدائ تا د خپلو خلقو بنى اِسرائيلو دپاره د بادشاه په توګه مقرروى. تۀ به د هغۀ په خلقو بادشاهى کوې او د ټولو دشمنانو نه به يې بچ کوې او دا هغه نښه ده چې تۀ مالِک خُدائ خوښ کړے يې او د هغوئ بادشاه جوړ شوے يې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6913, '1 Samuel 10:2', '1 Samuel', 10, 2, '&nbsp;چې تاسو نن زما نه لاړ شئ، نو د بنيامين په علاقه ضلضع کښې د راحيل د قبر سره نزدې به تاسو د دوو سړو سره مِلاو شئ. هغوئ به تاسو ته ووائى چې تاسو کوم خرونه لټوئ هغه پېدا شوى دى، نو داسې ستاسو پلار به د خرونو په حقله پرېشان نۀ وى خو ستاسو په حقله به پرېشان وى او بيا بيا به تپوسونه کوى چې زما زوئ چرته دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6914, '1 Samuel 10:3', '1 Samuel', 10, 3, '&nbsp;کله چې تاسو په تبور کښې پاکې ونې ته ورسېږئ، نو هلته به تاسو د درېو سړو سره مِلاو شئ چې په بيت‌ايل کښې خُدائ پاک ته يوه نذرانه پېش کولو له روان وى. يو به د چېلۍ درې بچى روان کړى وى، بل به درې روټۍ روانې کړې وى او درېم سره به د ميو نه ډکه مشکيزه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6915, '1 Samuel 10:4', '1 Samuel', 10, 4, '&nbsp;هغوئ به په تاسو سلام واچوى او دوه روټۍ به درته پېش کړى، هغه تاسو قبولې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6916, '1 Samuel 10:5', '1 Samuel', 10, 5, '&nbsp;بيا به تاسو په جبعه کښې د خُدائ پاک غر ته لاړ شئ، چرته چې د فلستيانو کېمپ دے. ښار ته د ننوتلو په ځائ کښې به تاسو د پېغمبرانو يوې قبيلې سره مِلاو شئ چې په غرۀ باندې د قربان‌ګاه نه راکوزيږى، بينجو، تمبل، شپېلۍ او رباب به غږوى. او هغوئ به په جذبه کښې پېغام ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6917, '1 Samuel 10:6', '1 Samuel', 10, 6, '&nbsp;د مالِک خُدائ روح به ناڅاپه په تاسو باندې راشى او تاسو به هم د هغوئ سره پېشګوئې شروع کړئ. او تاسو به هغه شان نۀ يئ لکه چې څنګه مخکښې وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6918, '1 Samuel 10:7', '1 Samuel', 10, 7, '&nbsp;کله چې دا نښې وشى نو تاسو هغه څۀ وکړئ چې څۀ مناسب وى، ځکه چې خُدائ پاک ستاسو مل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6919, '1 Samuel 10:8', '1 Samuel', 10, 8, '&nbsp;تاسو به زما نه مخکښې لاندې جِلجال ته لاړ شئ، هلته به زۀ ستاسو سره ملګرے شم او سوزېدونکې او د سلامتۍ نذرانې به پېش کړم. اووۀ ورځې هلته اِنتظار وکړئ تر دې پورې چې زۀ درشم او درته ووايم چې څۀ به کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6920, '1 Samuel 10:9', '1 Samuel', 10, 9, '&nbsp;کله چې ساؤل د سموئيل نه روان شو، نو خُدائ پاک ساؤل بېخى بدل کړو. او په هغه ورځ هغه هر څۀ وشول چې څۀ ورته سموئيل فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6921, '1 Samuel 10:10', '1 Samuel', 10, 10, '&nbsp;کله چې ساؤل او د هغۀ نوکر جبعه ته ورسېدل، نو د پېغمبرانو يوه ډله ورسره مِلاو شوه، د مالِک خُدائ روح ناڅاپه په هغۀ باندې راغلو او هغۀ د هغوئ سره پېشګوئې ورکول شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6922, '1 Samuel 10:11', '1 Samuel', 10, 11, '&nbsp;کومو خلقو چې هغه د مخکښې نه پېژندلو او چې هغوئ وليدلو چې دا هر څۀ يې کول نو هغوئ د يو بل نه تپوس وکړو، ”د قيس په زوئ باندې څۀ شوى دى؟ ساؤل پېغمبر شوے دے څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6923, '1 Samuel 10:12', '1 Samuel', 10, 12, '&nbsp;يو مقامى سړى ووئيل، ”کۀ د چا پلار څۀ هم وى نو ولې د هغۀ زوئ پېغمبر جوړېدے شى څۀ؟“ نو بيا دا يو متل جوړ شو، ”آيا ساؤل هم په نبيانو کښې شمېرلے شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6924, '1 Samuel 10:13', '1 Samuel', 10, 13, '&nbsp;کله چې ساؤل خپله پېشګوئې ختمه کړه نو هغه د عبادت ځائ ته وختلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6925, '1 Samuel 10:14', '1 Samuel', 10, 14, '&nbsp;د ساؤل ترۀ هغه او نوکر وليدل او تپوس يې ترې نه وکړو، ”تاسو چرته وئ؟“ ساؤل ورته په جواب کښې ووئيل، ”خرونه مو لټول. کله چې مونږ خرونه پېدا نۀ کړل نو د سموئيل سره مِلاوېدو له لاړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6926, '1 Samuel 10:15', '1 Samuel', 10, 15, '&nbsp;د ساؤل ترۀ ترې نه تپوس وکړو، ”او سموئيل تاسو ته څۀ ووئيل؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6927, '1 Samuel 10:16', '1 Samuel', 10, 16, '&nbsp;ساؤل جواب ورکړو، ”هغۀ مونږ ته ووئيل چې خرونه پېدا شوى دى.“ خو هغۀ خپل ترۀ ته د بادشاه کېدو په حقله ونۀ وئيل چې سموئيل ورته څۀ فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6928, '1 Samuel 10:17', '1 Samuel', 10, 17, '&nbsp;سموئيل په مصفاه کښې خلق د مالِک خُدائ په حضور کښې راغونډ کړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6929, '1 Samuel 10:18', '1 Samuel', 10, 18, '&nbsp;او هغوئ ته يې وفرمائيل، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک فرمائى چې ما تاسو د مِصر نه راوويستلئ او د مِصريانو او هغه نورو ټولو خلقو نه مې بچ کړئ چې کومو په تاسو باندې سختى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6930, '1 Samuel 10:19', '1 Samuel', 10, 19, '&nbsp;زۀ ستاسو خُدائ پاک يم، هغه څوک چې تاسو د ټولو تکليفونو او سختو نه بچ کوى، خو تاسو نن زۀ رد کړے يم او بادشاه مو رانه غوښتے دے. ډېره ښۀ ده، نو د مالِک خُدائ په وړاندې ډله په ډله او قبيله په قبيله راغونډ شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6931, '1 Samuel 10:20', '1 Samuel', 10, 20, '&nbsp;بيا سموئيل هره قبيله وړاندې راوستله او د بنيامين قبيله د پچې په ذريعه خوښه کړے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6932, '1 Samuel 10:21', '1 Samuel', 10, 21, '&nbsp;بيا سموئيل د بنيامين د قبيلو خاندان وړاندې راوستلې او د مِطرى خاندان خوښه کړے شو. بيا د مِطرى د خاندان سړى وړاندې راغلل او د قيس زوئ ساؤل خوښ کړے شو. هغوئ هغه ولټولو، خو چې کله يې هغه ونۀ موندلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6933, '1 Samuel 10:22', '1 Samuel', 10, 22, '&nbsp;نو هغوئ د مالِک خُدائ نه تپوس وکړو، ”هغه سړے تر اوسه پورې دلته راغلے دے څۀ؟“ مالِک خُدائ ورته وفرمائيل، ”ګورئ، هغه د بوجو په مينځ کښې پټ شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6934, '1 Samuel 10:23', '1 Samuel', 10, 23, '&nbsp;نو هغوئ منډه کړه او ساؤل يې بهر خلقو ته راوويستلو او هغه د خلقو په مينځ کښې ودرېدو. هغه د ټولو نه لوړ سړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6935, '1 Samuel 10:24', '1 Samuel', 10, 24, '&nbsp;سموئيل خلقو ته وفرمائيل، ”هغه سړے دا دے کوم چې مالِک خُدائ خوښ کړے دے. زمونږ په مينځ کښې د هغۀ په شان بل هيڅ څوک هم نشته.“ نو ټولو خلقو چغه کړه، ”بادشاه زِنده‌باد.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6936, '1 Samuel 10:25', '1 Samuel', 10, 25, '&nbsp;سموئيل خلقو ته د بادشاه حقُونه او ذمه وارۍ بيان کړې او بيا يې په يو کِتاب کښې وليکلې او کِتاب يې د مالِک خُدائ په حضور کښې کېښودو. بيا هغۀ ټول خلق کورونو ته ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6937, '1 Samuel 10:26', '1 Samuel', 10, 26, '&nbsp;ساؤل هم واپس په جبعه کښې خپل کور ته لاړو. يو څو تکړه سړى هم ورسره لاړل چې د هغوئ زړونه خُدائ پاک بدل کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6938, '1 Samuel 10:27', '1 Samuel', 10, 27, '&nbsp;خو څۀ شريرانو خلقو ووئيل، ”دا سړے به مونږ څنګه بچ کړى؟“ هغوئ د ساؤل سپکاوے وکړو او تُحفې يې ورله رانۀ وړې. خو ساؤل هيڅ جواب ورنۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6939, '1 Samuel 11:1', '1 Samuel', 11, 1, '&nbsp;تقريباً يوه مياشت وروستو عمونى بادشاه ناحس د جِلعاد په علاقه کښې د يبيس ښار خِلاف خپل لښکر روان کړو او ښار يې محاصره کړو. د يبيس سړو ناحس ته ووئيل، ”مونږ سره د صُلحې تړون وکړه، نو مونږ به تا خپل بادشاه ومنو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6940, '1 Samuel 11:2', '1 Samuel', 11, 2, '&nbsp;ناحس جواب ورکړو، ”زۀ به ستاسو سره په يو شرط باندې د صُلحې تړون وکړم، زۀ به د هر يو کس ښۍ سترګه وباسم او دا به د ټولو بنى اِسرائيلو دپاره د شرم خبره وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6941, '1 Samuel 11:3', '1 Samuel', 11, 3, '&nbsp;د يبيس مشرانو ووئيل، ”مونږ له اووۀ ورځې راکړئ چې مونږ د بنى اِسرائيلو ټول مُلک ته پېغام وړُونکى ولېږُو. کۀ مونږ هيچا هم بچ نۀ کړُو، نو مونږ به تاسو ته حواله شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6942, '1 Samuel 11:4', '1 Samuel', 11, 4, '&nbsp;پېغام وړُونکى جبعې ته ورسېدل، چرته چې ساؤل اوسېدو او کله يې چې ورته خبر بيان کړو نو خلقو په چغو چغو وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6943, '1 Samuel 11:5', '1 Samuel', 11, 5, '&nbsp;ساؤل د پټى نه غوَيى روان کړى وُو او تپوس يې وکړو، ”څۀ شوى دى؟ دا خلق ولې ژاړى؟“ چې کوم خبر پېغام وړونکو د يبيس نه راوړے وو نو هغوئ هغه ورته بيان کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6944, '1 Samuel 11:6', '1 Samuel', 11, 6, '&nbsp;کله چې ساؤل دا واورېدل نو د خُدائ پاک روح د لوئ طاقت سره په هغۀ نازل شو او ساؤل سخت غصه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6945, '1 Samuel 11:7', '1 Samuel', 11, 7, '&nbsp;هغۀ دوه غوَيى بوتلل، ټوټې ټوټې يې کړل او د دې خبردارى سره يې پېغام وړُونکى ولېږل چې د بنى اِسرائيلو ټول مُلک ته دا ټوټې يوسئ، ”څوک هم چې د جنګ دپاره په ساؤل او سموئيل پسې نۀ ځى نو د هغۀ د غوَيانو سره به دا چل کيږى.“ نو د دې په وجه د مالِک خُدائ يره په بنى اِسرائيلو باندې راغله او هغوئ ټول په يو ځائ راووتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6946, '1 Samuel 11:8', '1 Samuel', 11, 8, '&nbsp;ساؤل هغوئ په بزق کښې راغونډ کړل، هغوئ درې لاکه د بنى اِسرائيل نه وُو او دېرش زره د يهوداه د قبيلې کسان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6947, '1 Samuel 11:9', '1 Samuel', 11, 9, '&nbsp;هغوئ د يبيس پېغام وړونکو ته ووئيل، ”خپلو خلقو ته ووايئ چې سبا د غرمې نه مخکښې به هغوئ خلاص شى.“ کله چې د يبيس خلقو ته دا پېغام مِلاو شو، نو هغوئ ډېر خوشحاله شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6948, '1 Samuel 11:10', '1 Samuel', 11, 10, '&nbsp;او ناحس ته يې ووئيل، ”سبا به مونږ تا ته خپل ځان حواله کړُو او چې ستا څۀ خوښه وى نو هغه راسره وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6949, '1 Samuel 11:11', '1 Samuel', 11, 11, '&nbsp;په هغه شپه ساؤل خپل سړى په درېو ډلو کښې تقسيم کړل او هغوئ سحر وختى د دشمن په خېمو باندې تېز ورغلل او په عمونيانو باندې يې حمله وکړه. تر غرمې پورې يې ټول وژلى وُو. ژوندى پاتې کسان خوارۀ وارۀ شول، هر يو سړى په خپله مخه منډې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6950, '1 Samuel 11:12', '1 Samuel', 11, 12, '&nbsp;بيا خلقو سموئيل ته ووئيل، ”هغه خلق چرته دى چې کومو وئيل چې ساؤل به زمونږ بادشاه نۀ وى؟ هغوئ مونږ ته حواله کړه او مونږ به يې ووژنو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6951, '1 Samuel 11:13', '1 Samuel', 11, 13, '&nbsp;خو ساؤل ورته ووئيل، ”نن به هيڅ څوک هم نۀ شى وژلے، ځکه چې نن هغه ورځ ده چې مالِک خُدائ بنى اِسرائيليان بچ کړى وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6952, '1 Samuel 11:14', '1 Samuel', 11, 14, '&nbsp;او سموئيل هغوئ ته وفرمائيل، ”راځئ چې يو ځل بيا ټول جِلجال ته لاړ شُو او ساؤل دوباره خپل بادشاه جوړ کړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6953, '1 Samuel 11:15', '1 Samuel', 11, 15, '&nbsp;نو هغوئ ټول جِلجال ته لاړل او هلته يې په مقدس ځائ کښې د ساؤل د بادشاهۍ اِعلان وکړو. هغوئ د سلامتۍ نذرانې پېش کړې او ساؤل او د بنى اِسرائيلو ټولو خلقو يوه لويه خوشحالى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6954, '1 Samuel 12:1', '1 Samuel', 12, 1, '&nbsp;بيا سموئيل ټولو بنى اِسرائيلو ته وفرمائيل، ”تاسو چې ما ته څۀ وئيلى وُو نو ما هغه کړى دى. ما يو بادشاه درکړے دے چې په تاسو بادشاهى وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6955, '1 Samuel 12:2', '1 Samuel', 12, 2, '&nbsp;او اوس هغه ستاسو د لارښودنې دپاره تاسو سره دے. زۀ بوډا او سپين‌ږيرے يم او تاسو ته پته ده چې زما زامن تاسو سره دى. زۀ د ځوانۍ نه تر اوسه پورې ستاسو مشر وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6956, '1 Samuel 12:3', '1 Samuel', 12, 3, '&nbsp;زۀ ستاسو په وړاندې يم. کۀ ما څۀ غلط کار کړے وى، اوس اوس د مالِک خُدائ او د هغه بادشاه په مخکښې په ما اِلزام ولګوئ کوم چې مالِک خُدائ خوښ کړے دے. ما د چا غوَيے يا د چا خر بوتلے دے څۀ؟ ولې ما څوک دوکه کړے دے يا مې په چا ظلم کړے دے څۀ؟ ما د چا نه رشوت اخستے دے څۀ؟ کۀ ما دا يو کار هم کړے وى، نو ما چې څۀ هم اخستى وى هغه به واپس ورکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6957, '1 Samuel 12:4', '1 Samuel', 12, 4, '&nbsp;خلقو جواب ورکړو، ”نه، تا مونږ له نۀ دوکه راکړې ده او نۀ دې په مونږ ظلم کړے دے، تا د هيچا نه هيڅ هم نۀ دى اخستى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6958, '1 Samuel 12:5', '1 Samuel', 12, 5, '&nbsp;سموئيل ورته په جواب کښې وفرمائيل، ”مالِک خُدائ او هغۀ چې کوم بادشاه خوښ کړے دے نن د دې خبرې ګواهان دى چې زۀ بېخى بې‌ګناه يم.“ هغوئ ورته وفرمائيل، ”آو، مالِک خُدائ ګواه دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6959, '1 Samuel 12:6', '1 Samuel', 12, 6, '&nbsp;سموئيل وفرمائيل، ”مالِک خُدائ هغه څوک دے چا چې موسىٰ او هارون خوښ کړل او ستاسو پلار نيکۀ يې د مِصر نه راوويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6960, '1 Samuel 12:7', '1 Samuel', 12, 7, '&nbsp;اوس چې چرته يئ نو هم هلته ودرېږئ او زۀ به د مالِک خُدائ په مخکښې تاسو ودروم چې هغه ټول لوئ لوئ کارونه در په ياد کړم چې مالِک خُدائ ستاسو او ستاسو د پلار نيکۀ د بچ کولو دپاره کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6961, '1 Samuel 12:8', '1 Samuel', 12, 8, '&nbsp;کله چې يعقوب او د هغۀ خاندان مِصر ته لاړل، نو ستاسو پلار نيکۀ د مدد دپاره فرياد وکړو او هغۀ موسىٰ او هارون راولېږل او هغوئ ستاسو پلار نيکۀ د مِصر نه راوويستل او په دې مُلک کښې يې دېره کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6962, '1 Samuel 12:9', '1 Samuel', 12, 9, '&nbsp;خو خلقو مالِک خُدائ خپل خُدائ پاک هېر کړو، نو هغۀ هغوئ سِسيرا ته حواله کړل څوک چې د حصور د ښار د لښکر مشر وو او فلستيانو او د موآب بادشاه ته يې حواله کړل، چې هغوئ ستاسو د پلار نيکۀ خِلاف وجنګيږى او شکست ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6963, '1 Samuel 12:10', '1 Samuel', 12, 10, '&nbsp;بيا هغوئ مالِک خُدائ ته وئيل چې، مونږ ګناه کړې ده ځکه مونږ ستا نه واوړېدو او د بعل او عستارات د بُتانو عبادت مو وکړو. مونږ د خپلو دشمنانو نه بچ کړه او مونږ به ستا عبادت کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6964, '1 Samuel 12:11', '1 Samuel', 12, 11, '&nbsp;مالِک خُدائ جدعون، برق او اِفتاح راولېږل او په آخر کښې يې زۀ راولېږلم. مونږ هر يو تاسو د ګېرچاپېره دشمنانو نه بچ کړئ او تاسو په خېر سره ژوند تېرولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6965, '1 Samuel 12:12', '1 Samuel', 12, 12, '&nbsp;خو کله چې تاسو وليدل چې د عمون بادشاه ناحس په تاسو حمله کوى، نو تاسو مالِک خُدائ رد کړو اګر چې مالِک خُدائ ستاسو خُدائ پاک ستاسو بادشاه وو خو تاسو بيا هم ما ته ووئيل چې مونږ يو بادشاه غواړُو چې په مونږ بادشاهى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6966, '1 Samuel 12:13', '1 Samuel', 12, 13, '&nbsp;نو اوس هغه بادشاه دا دے چې تاسو خوښ کړے دے، تاسو هغه غوښتے وو او مالِک خُدائ تاسو له درکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6967, '1 Samuel 12:14', '1 Samuel', 12, 14, '&nbsp;کۀ تاسو د مالِک خُدائ نه يرېږئ، د هغۀ خِدمت او تابعدارى کوئ او د هغۀ د حُکم نه سرکشى مۀ کوئ او کۀ تاسو او هغه بادشاه چې په تاسو بادشاهى کوى د مالِک خُدائ د خپل خُدائ پاک تابعدارى کوئ نو ستاسو هر کار به سم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6968, '1 Samuel 12:15', '1 Samuel', 12, 15, '&nbsp;خو کۀ تاسو مالِک خُدائ ته غوږ نۀ نيسئ او د هغۀ د حُکمونو نافرمانى کوئ، نو هغه به ستاسو او ستاسو د بادشاه خِلاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6969, '1 Samuel 12:16', '1 Samuel', 12, 16, '&nbsp;نو بيا دلته ودرېږئ او تاسو به په خپلو سترګو هغه لوئ لوئ کارونه ووينئ چې مالِک خُدائ يې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6970, '1 Samuel 12:17', '1 Samuel', 12, 17, '&nbsp;تاسو ته پته ده چې دا د غنمو د لَو وخت دے چې دا د باران موسم نۀ وى خو زۀ به مالِک خُدائ ته سوال وکړم او هغه به تندر او باران راولېږى. کله چې داسې وشى نو تاسو ته به پته ولګى چې تاسو د مالِک خُدائ خِلاف يوه لويه ګناه کړې ده کله چې تاسو د هغۀ نه يو بادشاه وغوښتو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6971, '1 Samuel 12:18', '1 Samuel', 12, 18, '&nbsp;نو سموئيل سوال وکړو او هم په هغه ورځ مالِک خُدائ تندر او باران راولېږلو. نو ټول خلق د مالِک خُدائ او سموئيل نه ويرېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6972, '1 Samuel 12:19', '1 Samuel', 12, 19, '&nbsp;او هغوئ سموئيل ته ووئيل، ”مالِک خُدائ خپل خُدائ پاک ته زمونږ دپاره سوال وکړه، نو داسې به مونږ نۀ مړۀ کيږُو. اوس مونږ ته دا پته لګېدلې ده چې د نورو ټولو ګناهونو نه علاوه مونږ دا ګناه هم کړې ده چې يو بادشاه مو غوښتے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6973, '1 Samuel 12:20', '1 Samuel', 12, 20, '&nbsp;سموئيل ورته وفرمائيل، ”مۀ يرېږئ، اګر چې تاسو داسې بد عمل کړے هم دے خو د مالِک خُدائ نه مۀ اوړئ او د خپل ټول زړۀ سره د هغۀ خِدمت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6974, '1 Samuel 12:21', '1 Samuel', 12, 21, '&nbsp;د بې‌کاره بُتانو عبادت دپاره واپس مۀ ورګرځئ، هغه بُتان نۀ ستاسو مدد کولے شى او نۀ مو بچ کولے شى، ځکه چې دا بې‌کاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6975, '1 Samuel 12:22', '1 Samuel', 12, 22, '&nbsp;مالِک خُدائ به د خپل نوم د خاطره تاسو نۀ پرېږدى، ځکه چې د هغۀ دا خوښه ده چې تاسو خپل خلق جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6976, '1 Samuel 12:23', '1 Samuel', 12, 23, '&nbsp;باقى پاتې شوه زما خبره، نو مالِک خُدائ دې ونۀ کړى چې د هغۀ خِلاف داسې ګناه وکړم چې هغۀ ته ستاسو دپاره سوال نۀ کوم. او زۀ به تاسو ته هغه لار ښايم چې کومه ښۀ او صحيح وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6977, '1 Samuel 12:24', '1 Samuel', 12, 24, '&nbsp;د مالِک خُدائ نه يره په کار ده او د زړۀ د اخلاصه په وفادارۍ سره د هغۀ خِدمت کوئ. هغه لوئ لوئ کارونه راپه ياد کړئ چې هغۀ ستاسو دپاره کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6978, '1 Samuel 12:25', '1 Samuel', 12, 25, '&nbsp;خو کۀ تاسو بيا هم خپله بدعملى کوئ نو تاسو او ستاسو بادشاه به تباه شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6979, '1 Samuel 13:1', '1 Samuel', 13, 1, '&nbsp;ساؤل د دېرشو کالو په عُمر کښې بادشاه جوړ شو او هغۀ دوه څلوېښت کاله په بنى اِسرائيلو بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6980, '1 Samuel 13:2', '1 Samuel', 13, 2, '&nbsp;ساؤل درې زره سړى خوښ کړل، دوه زره يې د ځان سره په مِکماس کښې او د غرونو مُلک بيت‌ايل کښې وساتل او زر سړى يې د خپل زوئ يونتن سره جبعې ته ولېږل چې د بنيامين د قبيلې علاقه ده. باقى پاتې سړى ساؤل کورونو ته ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6981, '1 Samuel 13:3', '1 Samuel', 13, 3, '&nbsp;يونتن په فلستيانو حمله وکړه او په جبعه کښې يې د هغوئ قلعه تباه کړه او ټول فلستيان د دې نه خبر شول. بيا ساؤل پېغام وړُونکى ولېږل چې عبرانيان د جنګ دپاره راوغواړى او په ټول مُلک کښې يې د خبردارى دپاره بيګلې وغږولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6982, '1 Samuel 13:4', '1 Samuel', 13, 4, '&nbsp;نو ټول بنى اِسرائيليان خبر شول چې ساؤل فلستىے مشر وژلے دے او دا چې فلستيان ستاسو نه نور نفرت هم کوى. نو خلق راغونډ شول او په جِلجال کښې د ساؤل سره شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6983, '1 Samuel 13:5', '1 Samuel', 13, 5, '&nbsp;فلستيان د بنى اِسرائيلو خِلاف د جنګ دپاره راغونډ شول، د هغوئ سره دېرش زره جنګى ګاډۍ وې، شپږ زره په آسونو سوارۀ کسان او دومره ډېر فوجيان ورسره وُو لکه چې په سمندر کښې څومره شګې دى. هغوئ د بيت‌آون نمرخاتۀ طرف ته مِکماس ته لاړل او هلته يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6984, '1 Samuel 13:6', '1 Samuel', 13, 6, '&nbsp;کله چې بنى اِسرائيلو وليدل چې حالات نازک دى او د هغوئ لښکر د سختۍ سره مخ دے، نو هغوئ د ګټو په غارونو او سورو کښې، ونو بوټو او په کُوهو کښې پټ شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6985, '1 Samuel 13:7', '1 Samuel', 13, 7, '&nbsp;هغه نور د جاد او جِلعاد علاقې ته د اُردن سيند نه پورې وتل. ساؤل تر اوسه پورې په جِلجال کښې وو او د هغۀ سره چې کوم خلق وُو هغوئ د يرې نه ريږدېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6986, '1 Samuel 13:8', '1 Samuel', 13, 8, '&nbsp;هغۀ اووۀ ورځې د سموئيل اِنتظار وکړو، لکه څنګه چې سموئيل ورته فرمائيلى وُو، خو سموئيل بيا هم جِلجال ته رانۀ غلو. نو خلقو د ساؤل په پرېښودو شروع وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6987, '1 Samuel 13:9', '1 Samuel', 13, 9, '&nbsp;نو هغۀ ورته ووئيل، ”ما له سوزېدونکې نذرانې او د سلامتۍ نذرانې راوړئ.“ او هغۀ په خپله يوه سوزېدونکې نذرانه پېش کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6988, '1 Samuel 13:10', '1 Samuel', 13, 10, '&nbsp;او چې څنګه يې نذرانه ختمه کړه، نو سموئيل راورسېدو. ساؤل هغۀ سره مِلاوېدو او ستړى مشى له ورَغلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6989, '1 Samuel 13:11', '1 Samuel', 13, 11, '&nbsp;خو سموئيل وفرمائيل، ”تا څۀ کړى دى؟“ ساؤل جواب ورکړو، ”خلق زما نه تلل، خو چې تا څنګه فرمائيلى وُو نو تۀ په مقرر وخت رانۀ غلې، د دې نه علاوه، فلستيان په مِکماس کښې د جنګ دپاره راغونډيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6990, '1 Samuel 13:12', '1 Samuel', 13, 12, '&nbsp;نو زما خيال دا وو چې فلستيان دلته په ما باندې په جِلجال کښې حمله کوى، خو ما مالِک خُدائ ته سوال نۀ وو کړے او زۀ مجبور وم چې نذرانه پېش کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6991, '1 Samuel 13:13', '1 Samuel', 13, 13, '&nbsp;سموئيل ورته په جواب کښې وفرمائيل، ”داسې کول بې‌وقوفى وه. تا د مالِک خُدائ خپل خُدائ پاک حُکم نۀ دے منلے. کۀ تا منلے وے نو هغۀ به تۀ او ستا اولاد بادشاهان جوړ کړى وئ چې همېشه دپاره په بنى اِسرائيلو حکومت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6992, '1 Samuel 13:14', '1 Samuel', 13, 14, '&nbsp;خو اوس به ستا بادشاهى ختمه شى. ځکه چې تا د هغۀ نافرمانى کړې ده، مالِک خُدائ يو داسې سړے لټولے دے چې د هغۀ خوښ وو او هغه يې د خپلو خلقو بادشاه مقرر کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6993, '1 Samuel 13:15', '1 Samuel', 13, 15, '&nbsp;سموئيل د جِلجال نه روان شو او په خپله مخه لاړو. پاتې خلق په ساؤل پسې لاړل چې د فوجيانو سره شامل شى، هغوئ د جِلجال نه د بنيامين په علاقه کښې جبعې ته لاړل. ساؤل د خپل لښکر معائنه وکړه چې تقريباً شپږ سوه سړى پاتې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6994, '1 Samuel 13:16', '1 Samuel', 13, 16, '&nbsp;ساؤل، د هغۀ زوئ يونتن او د دوئ سړو د بنيامين په علاقه جبعه کښې خېمې ولګولې، د فلستيانو خېمې په مِکماس کښې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6995, '1 Samuel 13:17', '1 Samuel', 13, 17, '&nbsp;فلستى فوجيان په درېو ډلو کښې د حملې دپاره د خپلو خېمو نه ووتل، يوه قبيله د سعال په علاقه کښې عفره ته لاړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6996, '1 Samuel 13:18', '1 Samuel', 13, 18, '&nbsp;بله ډله بيت‌حورون طرف ته لاړه او هغه بله يوه د حد پولې ته لاړه چې د کوم ځائ نه د صبوئيم وادى او بيابان ښکارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6997, '1 Samuel 13:19', '1 Samuel', 13, 19, '&nbsp;(په بنى اِسرائيلو کښې لوهار نۀ وو ځکه چې د فلستيانو اراده دا وه چې عبرانيان تُورې او نېزې جوړې نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6998, '1 Samuel 13:20', '1 Samuel', 13, 20, '&nbsp;بنى اِسرائيليان به د خپلو يوو، ګينټو، تبرُونو او لورونو تېرولو دپاره فلستيانو له تلل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6999, '1 Samuel 13:21', '1 Samuel', 13, 21, '&nbsp;د تبرُونو او لورونو د تېرۀ کولو او د غوَيى د سامان مرمت کولو مزدورى يوه وړه سيکه وه او دوه سيکې د يوې او ګينټۍ تېرۀ کولو دپاره وې.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7000, '1 Samuel 13:22', '1 Samuel', 13, 22, '&nbsp;نو د جنګ په هغه ورځ باندې د ساؤل او د هغۀ زوئ يونتن نه بغېر د يو بنى اِسرائيلى فوجى سره هم تُوره يا نېزه نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');